package com.hrflow.controller; import org.springframework.beans.factory.annotation.Value;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*; @RestController@RequestMapping("/api/files") public class FileController{@Value("${FILE_STORAGE_PATH:./storage}")String root;@PostMapping("/upload")@PreAuthorize("isAuthenticated()")public Map<String,Object> upload(@RequestParam MultipartFile file)throws Exception{if(file.isEmpty()||file.getSize()>10_000_000)throw new IllegalArgumentException("Invalid file");String n=UUID.randomUUID()+"-"+Path.of(Objects.requireNonNull(file.getOriginalFilename())).getFileName();Files.createDirectories(Path.of(root));Path p=Path.of(root).resolve(n);Files.write(p,file.getBytes());return Map.of("fileName",n,"size",file.getSize(),"contentType",file.getContentType());}}
